'use strict';
function productBuildDraft(mode='ai',roundId,preserve=false){
 const i=issue(),s=investigation(),old=i.productDraft||i.handoffDraft;
 const h=mode==='ai'?AI.handoff(s,roundId||lastAnswer(s)?.id):{round:null,question:'人工调查记录',body:'',unknown:'',next:'',evidence:s.context.filter(e=>P.availability(i,e)==='available'),verifications:s.hypotheses.flatMap(h=>(h.history||[]).map(v=>({...v,hypothesis:h.id}))),hypotheses:s.hypotheses};
 i.productDraft={id:'UPDATE-'+crypto.randomUUID(),mode,round:h.round,scopeToken:P.token(i),snapshot:JSON.parse(JSON.stringify(h)),evidence:JSON.parse(JSON.stringify(h.evidence)),owner:preserve&&old?.owner!==undefined?old.owner:(i.owner==='待分配'?'':i.owner),status:preserve&&old?.status?old.status:(i.status==='已解决'?'重新调查':['待修复','待验证','调查中'].includes(i.status)?i.status:'调查中'),summary:preserve&&old?.summary!==undefined?old.summary:mode==='ai'?handoffText(h):`问题：${i.title}\n\n已知事实：\n\n仍待确认：\n\n下一步：`,confirmed:false};
 save();return i.productDraft;
}
inlineHandoff=function(){
 const i=issue(),s=investigation();let d=i.productDraft;
 if(!d){try{d=productBuildDraft(lastAnswer(s)?'ai':'manual',null,!!i.handoffDraft);}catch(e){return '<div class="notice">'+esc(e.message)+'</div>';}}
 const stale=d.scopeToken!==P.token(i),bad=productBlocked(i,d.evidence),fix=productState().fixes?.at(-1);
 return `<section class="product-card product-handoff"><div class="product-kicker">调查结果 → 预览核对 → 保存更新</div><label for="handoff-mode">结果来源</label><select id="handoff-mode" onchange="productSwitchMode(this.value)"><option value="manual" ${d.mode==='manual'?'selected':''}>人工调查记录 · 无需 AI 回答</option><option value="ai" ${d.mode==='ai'?'selected':''} ${!lastAnswer(s)?'disabled':''}>AI 已完成轮次 + 人工复核</option></select>${d.mode==='ai'?`<label for="handoff-round">引用的已完成回答</label><select id="handoff-round" onchange="productSelectRound(this.value)">${s.rounds.filter(r=>r.status==='done').map(r=>`<option value="${r.id}" ${r.id===d.round?'selected':''}>${esc(r.id+' · '+r.question.slice(0,50))}</option>`).join('')}</select>`:'<p class="muted">保存人工作者与证据来源；不会将失败或中断的 AI 回答自动当成人工结论。</p>'}
 ${stale?`<div class="notice" role="alert"><b>预览后内容已变化</b><p>工单、证据或验证已更新。你的编辑已保留，重新预览后再确认。</p>${btn('重新预览，保留我的编辑','productRefreshDraft()','primary')}</div>`:''}
 ${bad.length?'<div class="notice">草稿中有不可用证据，暂不展示可能包含摘录的正文。请管理证据可用性，或新建人工记录。</div>':''}
 <form id="product-handoff-form" oninput="persistHandoff()" onchange="persistHandoff()" onsubmit="saveChatTicket(event)"><div class="form-grid"><label>工单状态<select id="chat-ticket-status">${['调查中','待修复','待验证','已解决','重新调查'].map(v=>`<option ${v===d.status?'selected':''}>${v}</option>`).join('')}</select></label><label>负责人<input id="chat-ticket-owner" required value="${esc(d.owner)}" placeholder="填写处理负责人"></label></div><label for="chat-ticket-summary">可编辑的调查结果</label><textarea id="chat-ticket-summary" class="long" required ${bad.length?'disabled':''}>${bad.length?'内容暂不可用':esc(d.summary)}</textarea>
 <details class="product-card"><summary>将保存的证据与验证 · ${d.evidence.length} 项证据</summary>${d.evidence.map(e=>`<p>${esc(e.label)} · ${esc(e.task)} · ${esc(availabilityNames[P.availability(i,e)])}</p>`).join('')||'<p>尚无证据。可以记录未知项，但不能关闭工单。</p>'}<p>假设验证 ${d.snapshot.verifications.length} 条 · 修复验证 ${productState().fixes?.length||0} 条</p></details>
 <div class="product-fix-summary"><b>关闭条件</b><p>${fix?`最新修复验证：${esc({pass:'通过',fail:'失败',inconclusive:'无法确定'}[fix.outcome])} · 构建 ${esc(fix.build)} · 执行人 ${esc(fix.actor)}`:'尚未记录独立修复验证。'}</p><small>先保存为待验证，再记录并复核通过的修复验证。假设支持、AI 回答或勾选核对不能代替。</small>${btn('查看或记录修复验证',"deskTool('hypotheses')")}</div>
 <label class="check"><input id="chat-ticket-confirm" type="checkbox" ${d.confirmed?'checked':''}>我已核对事实、推断、未知项与验证记录</label><p id="chat-ticket-error" class="error" role="alert"></p><div class="toolbar"><button class="primary" ${stale||bad.length?'disabled':''}>确认保存到工单</button><button type="button" onclick="productRefreshDraft()">重新预览，保留编辑</button></div><small>只保存浏览器本地工单；一次草稿只生成一条更新记录。</small></form>
 <details class="product-card"><summary>演练多人修改</summary><p>模拟另一位同事更新此工单版本，保留正文，用于检查陈旧草稿提示。</p>${btn('模拟工单版本更新','productConflict()')}</details></section>`;
};
persistHandoff=function(){const d=issue().productDraft;if(!d||!$('#product-handoff-form'))return;d.owner=$('#chat-ticket-owner').value;d.status=$('#chat-ticket-status').value;if(!$('#chat-ticket-summary').disabled)d.summary=$('#chat-ticket-summary').value;d.confirmed=$('#chat-ticket-confirm').checked;save();};
function productSwitchMode(mode){persistHandoff();try{productBuildDraft(mode,null,true);render();}catch(e){toast(e.message);}}
function productSelectRound(id){persistHandoff();try{productBuildDraft('ai',id,false);render();}catch(e){toast(e.message);}}
function productRefreshDraft(){persistHandoff();const d=issue().productDraft;try{productBuildDraft(d.mode,d.round,true);render();toast('已更新证据和验证范围，编辑内容保留，请重新核对');}catch(e){toast(e.message);}}
regenerateHandoff=productRefreshDraft;
function productConflict(){persistHandoff();productState().revision=(productState().revision||0)+1;save();render();}
chatTicket=function(roundId){persistHandoff();try{productBuildDraft('ai',roundId||lastAnswer()?.id,false);deskTool('handoff');}catch(e){toast(e.message);}};
ticket=function(){deskTool('handoff');};
saveChatTicket=function(event){event.preventDefault();persistHandoff();const i=issue(),d=i.productDraft,backup=JSON.stringify(state);try{P.commitHandoff(i,d);delete i.productDraft;delete i.handoffDraft;draftHandoff=null;if(!save()){state=JSON.parse(backup);throw Error('本地存储不足，未保存；草稿和原记录保留');}desk.tool='result';workUI.issueMode='result';render();toast('已保存调查、证据与验证，一次草稿仅写入一次');}catch(e){if($('#chat-ticket-error'))$('#chat-ticket-error').textContent=e.message;else toast(e.message);}};
function productFixPanel(){const fixes=productState().fixes||[];return `<section class="product-card"><span class="eyebrow">修复验证 · 与假设验证分开</span><h3>修复是否在目标场景生效？</h3><p>记录构建、预期与实际结果；验证由人执行和记录，原型不执行复现。</p>${btn('记录修复验证','productFixForm()','primary')}<div class="product-fix-history">${fixes.slice().reverse().map(v=>`<details><summary>${esc({pass:'通过',fail:'失败',inconclusive:'无法确定'}[v.outcome])} · ${esc(v.build)} · ${esc(v.actor)}</summary><p>场景：${esc(v.scenario)}</p><p>预期：${esc(v.expected)}</p><p>实际：${esc(v.actual)}</p><p>${v.evidence.length} 项证据 · ${esc(v.time)}</p></details>`).join('')||'<p class="muted">尚无修复验证记录；下方为假设验证。</p>'}</div></section>`;}
function productFixForm(){const candidates=investigation().context.filter(e=>P.availability(issue(),e)==='available');openModal('记录修复验证',`<form onsubmit="productSaveFix(event)"><div class="form-grid"><label>验证构建 *<input id="fix-build" required placeholder="实际验证的修复构建"></label><label>执行人 *<input id="fix-actor" required placeholder="谁实际执行了验证"></label></div><label>场景与验证步骤 *<textarea id="fix-scenario" required></textarea></label><label>预期结果 *<textarea id="fix-expected" required></textarea></label><label>实际观察 *<textarea id="fix-actual" required></textarea></label><label>修复验证结论<select id="fix-outcome"><option value="inconclusive">无法确定</option><option value="pass">通过</option><option value="fail">失败</option></select></label><label>关联现场证据 *</label>${candidates.map(e=>`<label class="check"><input type="checkbox" name="fix-evidence" value="${esc(e.id)}">${esc(e.label)}</label>`).join('')||'<p class="notice">当前没有可用证据。先从日志、源码或手动片段补充观察依据。</p>'}<p id="fix-error" class="error" role="alert"></p><div class="toolbar"><button class="primary">保存修复验证</button><button type="button" onclick="closeModal()">取消</button></div></form>`,true);}
function productSaveFix(event){event.preventDefault();const ids=[...document.querySelectorAll('input[name="fix-evidence"]:checked')].map(e=>e.value);const record={id:'FIX-'+crypto.randomUUID(),build:$('#fix-build').value.trim(),actor:$('#fix-actor').value.trim(),scenario:$('#fix-scenario').value.trim(),expected:$('#fix-expected').value.trim(),actual:$('#fix-actual').value.trim(),outcome:$('#fix-outcome').value,evidence:investigation().context.filter(e=>ids.includes(e.id)&&P.availability(issue(),e)==='available').map(e=>JSON.parse(JSON.stringify(e))),time:new Date().toLocaleString('zh-CN')};try{P.validateFix(record);const p=productState();p.fixes=p.fixes||[];p.fixes.push(record);investigation().revision++;save();closeModal();render();toast('已追加修复验证。回写草稿需重新预览，历史验证保留。');}catch(e){$('#fix-error').textContent=e.message;}}
const productDeskPanel=deskPanel;
deskPanel=function(x){return (desk.tool==='hypotheses'?productFixPanel():'')+productDeskPanel(x);};
const productDeskResult=deskResult;
deskResult=function(){return productDeskResult()+`<section class="product-card"><h3>继续更新调查</h3><p>可直接记录人工调查，也可选择已完成的 AI 回答；已解决的工单需先重新调查。</p>${btn('人工更新工单',"productBuildDraft('manual',null,false);deskTool('handoff')")}${btn('查看修复验证',"deskTool('hypotheses')")}</section>`;};
render();
const productFinalResult=deskResult;
deskResult=function(){let html=productFinalResult().replace('onclick="deskTool(\'handoff\')" disabled','onclick="deskTool(\'handoff\')"');const unavailable=issue().updates.some(u=>productBlocked(issue(),u.investigation?.evidence).length);if(unavailable)return `<section class="product-card"><h3>历史更新引用了不可用证据</h3><p>保存记录仍保留，含证据摘录的正文暂不可读。可管理证据可用性，或新建人工更新。</p>${btn('管理证据',"deskTool('evidence')")}${btn('新建人工更新',"productBuildDraft('manual',null,false);deskTool('handoff')")}</section>`;const latest=issue().updates[0];if(latest)html=html.replace((latest.investigation?.verifications.length||0)+' 条验证', (latest.investigation?.verifications.length||0)+' 条假设验证 · '+(latest.investigation?.fixVerifications?.length||0)+' 条修复验证');return html;};
exportConversation=function(){const i=issue(),s=investigation(),all=[...s.context,...s.rounds.flatMap(r=>r.snapshot),...i.updates.flatMap(u=>u.investigation?.evidence||[])];if(productBlocked(i,all).length)return toast('调查或历史更新包含不可用证据，导出暂不可用');const r=lastAnswer(s);file(i.id+'-investigation-demo.txt',(r?handoffText(AI.handoff(s,r.id)):'人工调查，尚无完成的 AI 回答')+'\n\n工单更新历史\n'+i.updates.map(u=>u.time+' · '+u.owner+' · '+u.status+'\n'+u.summary).join('\n\n')+'\n\n修复验证\n'+JSON.stringify(productState().fixes||[],null,2)+'\n\n完整对话\n'+s.rounds.map(r=>r.id+' '+r.status+'\n问题：'+r.question+'\n'+(r.answer?.body||'本轮未完成')+'\n范围：'+r.snapshot.map(e=>e.label+' / '+e.task).join('；')).join('\n\n'));};
downloadReport=exportConversation;
